import sys, os, subprocess, shutil, pathlib, json
sys.path.insert(0,'/tmp')
from setup_repo import make_repo
def run_idea(label, modify=None, editor="/tmp/fake_editor.sh"):
    make_repo("/tmp/ideas")
    if modify: modify()
    home="/tmp/fh" # config already? recreate config
    shutil.rmtree(home, ignore_errors=True); os.makedirs(home+"/.config/eureka")
    pathlib.Path(home+"/.config/eureka/config.json").write_text(json.dumps({"repo":"/tmp/ideas"}))
    try: os.remove("/tmp/editor.log")
    except: pass
    env=dict(os.environ); env["HOME"]=home
    for k in ["EDITOR","VISUAL","PAGER","XDG_CONFIG_HOME"]: env.pop(k,None)
    env["EDITOR"]=editor; env["RUST_LOG"]="debug"
    with open("/tmp/out.bin","wb") as out, open("/tmp/err.bin","wb") as err:
        try:
            p=subprocess.run(["/workspace/executable"], input=b"Idea summary x\n", stdout=out, stderr=err, env=env, timeout=3)
            code=p.returncode
        except subprocess.TimeoutExpired: code="TIMEOUT"
    print(f"### {label} exit={code} out={pathlib.Path('/tmp/out.bin').read_bytes()[:600]!r} err={pathlib.Path('/tmp/err.bin').read_bytes()!r}")
    try: print(" editor.log:", pathlib.Path("/tmp/editor.log").read_text())
    except: print(" no editor.log")
    out=subprocess.run("git log --oneline -2; git status --short", shell=True, cwd="/tmp/ideas", capture_output=True, text=True)
    print(" git:", out.stdout, out.stderr)
    print(" README exists?", os.path.lexists("/tmp/ideas/README.md"), os.path.isdir("/tmp/ideas/README.md") if os.path.exists("/tmp/ideas/README.md") else "")

def del_readme(): os.remove("/tmp/ideas/README.md")
def readme_dir(): os.remove("/tmp/ideas/README.md"); os.makedirs("/tmp/ideas/README.md")
def readme_000(): os.chmod("/tmp/ideas/README.md",0)
def readme_fifo(): os.remove("/tmp/ideas/README.md"); os.mkfifo("/tmp/ideas/README.md")
def readme_dangling(): os.remove("/tmp/ideas/README.md"); os.symlink("/nonexistent","/tmp/ideas/README.md")
run_idea("README missing", del_readme)
run_idea("README dir", readme_dir)
run_idea("README 000", readme_000)
run_idea("README fifo", readme_fifo)
run_idea("README dangling", readme_dangling)
PY
python3 /tmp/case_idea_files.py 2>&1"}

