from setup_repo import make_repo
make_repo("/tmp/ideas")
os.remove("/tmp/ideas/README.md"); os.mkfifo("/tmp/ideas/README.md")
home="/tmp/fh"; shutil.rmtree(home, ignore_errors=True); os.makedirs(home+"/.config/eureka"); pathlib.Path(home+"/.config/eureka/config.json").write_text(json.dumps({"repo":"/tmp/ideas"}))
