fn init_logger() {
    let mut builder = env_filter::Builder::new();
    if let Ok(spec) = env::var("RUST_LOG") {
        if spec.matches('/').count() > 1 {
            // The whole specification is ignored in this case.
            eprintln!(
                "warning: invalid logging spec '{}', ignoring it (too many '/'s)",
                spec
            );
        } else if let Some(idx) = spec.find('/') {
            let regex_part = &spec[idx + 1..];
            match regex::Regex::new(regex_part) {
                Ok(_) => {
                    // Valid regex: let env_filter parse the whole spec.
                    // (Its warnings for any invalid directives in the
                    // module part already use the expected format.)
                    builder.parse(&spec);
                }
                Err(e) => {
                    eprintln!("warning: invalid regex filter - {}", e);
                    let mods = &spec[..idx];
                    for token in mods.split(',') {
                        let mut tmp_builder = env_filter::Builder::new();
                        // Validate this single token against a fresh
                        // builder so invalid directives are reported
                        // once and skipped, mirroring the reference
                        // parser. Valid tokens are applied to the real
                        // builder below by parsing the token again is
                        // unsafe (would re-report); instead, apply it by
                        // parsing the token into the real builder only
                        // when the fresh validation succeeds.
                        match tmp_builder.try_parse(token) {
                            Ok(_) => {
                                // Parse into the real builder; this token
                                // is known to be valid, so no warning is
                                // emitted for it.
                                let mut apply = env_filter::Builder::new();
                                let _ = apply.try_parse(token);
                                // Transfer is not directly possible, so
                                // fall back to parsing on the real builder
                                // (valid token, so silent).
                                builder.parse(token);
                                drop(apply);
                            }
                            Err(err) => {
                                print_parse_warning(&parse_error_details(&err));
                            }
                        }
                    }
                }
            }
        } else {
            // No regex part: validate each comma-separated directive
            // individually so warnings use the original formatting.
            for token in spec.split(',') {
                let mut tmp_builder = env_filter::Builder::new();
                match tmp_builder.try_parse(token) {
                    Ok(_) => {
                        builder.parse(token);
                    }
                    Err(err) => {
                        print_parse_warning(&parse_error_details(&err));
                    }
                }
            }
        }
    }
    let filter = builder.build();
    let max_level = filter.filter();
    let logger = Box::new(EurekaLogger { filter });
    if log::set_logger(Box::leak(logger)).is_ok() {
        log::set_max_level(max_level);
    }
}

